mapper.select:
SELECT id, storage_no, purchase_id, order_no, apply_no, storage_date, storage_status, operator_id, operator_name, total_amount, remark, create_user, create_time, update_time FROM asset_in_storage WHERE 1=1
AND storage_no LIKE CONCAT('%', #{storageNo}, '%')
AND order_no LIKE CONCAT('%', #{orderNo}, '%')
AND apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND storage_status = #{storageStatus}
AND DATE(storage_date) >= #{startDate}
AND DATE(storage_date) <= #{endDate}
ORDER BY create_time DESC

